cmux:
clear; D="${CMUX_CUSTOMIZE_DIR:-${XDG_CONFIG_HOME:-$HOME/.config}/cmux/customize}"; mkdir -p "$D/web"; pg() { printf '<!doctype html>
<html><head><meta charset="utf-8"><title>Web pane</title><link rel="stylesheet" href="page.css"></head>
<body><h1>%s</h1><p>This pane is the extension page, served from its web folder.</p></body></html>
' "$1"; }; css() { printf 'body { font: 15px -apple-system, sans-serif; color: var(--cmux-text, CanvasText); padding: 24px; }
h1 { color: var(--cmux-accent, AccentColor); }
'; }; mf() { printf '{"manifestVersion": 2, "id": "local/customize", "name": "Web pane probe", "version": "1.0.0", "description": "A web pane the tour rewrites.", "engines": {"cmux": "^2.0"}, "runtime": {"web": {"root": "web"}}, "implements": {"cmux.pane/1": {"web": "web/index.html", "title": "Web pane probe", "symbol": "globe"}}, "files": ["web/"]}
'; }; echo "customize folder: $D"
